class Multiplier(private val factor: Int) {
    operator fun invoke(value: Int): Int = value * factor
}

val triple = Multiplier(3)
println(triple(10)) // 30 — calls invoke() under the hood

inline fun <T> measureAndLog(label: String, block: () -> T): T {
    val start = System.nanoTime()
    val result = block()
    println("$label took ${(System.nanoTime() - start) / 1_000_000}ms")
    return result
}

