sealed interface DownloadState {
    data object Idle : DownloadState
    data class InProgress(val percent: Int) : DownloadState
    data class Failed(val error: Throwable) : DownloadState
}

inline fun runInBackground(crossinline action: () -> Unit) {
    thread { action() } // action is invoked from another execution context
    // without crossinline, a non-local return inside action would be illegal here
}

inline fun setup(inlinedAction: () -> Unit, noinline storedCallback: () -> Unit) {
    inlinedAction() // inlined directly
    registry.save(storedCallback) // must be a real object reference to store
}

inline fun forEachInline(items: List<Int>, action: (Int) -> Unit) { for (i in items) action(i) }

fun findFirstEven(items: List<Int>): Int? {
    forEachInline(items) { if (it % 2 == 0) return it } // legal — inline function
    return null
}

